solution:
function primeFactors(n) {
  const isPrime = (k) => {
    if (k < 2) return false;
    for (let d = 2; d < k; d++) if (k % d === 0) return false;
    return true;
  };
  const result = [];
  for (let d = 2; d <= n; d++) {
    if (n % d === 0 && isPrime(d)) result.push(d);
  }
  return result;
}

